#include <vector>
#include <unordered_set>
#include <algorithm>

using namespace std;

class Solution {
public:
    int closestToTarget(vector<int>& arr, int target) {
        unordered_set<int> prev;
        int res = INT_MAX;
        for (int num : arr) {
            unordered_set<int> curr;
            curr.insert(num);
            for (int x : prev)
                curr.insert(x & num);
            for (int x : curr)
                res = min(res, abs(x - target));
            prev = move(curr);
        }
        return res;
    }
};
